pm.sendRequest({
          url: pm.environment.get("baseurl") + ":" + pm.environment.get("risk-management-service-port") + "/api/auth/login",
          method: "POST",
          header: {
              "Content-Type": "application/json"
          },
          body: {
              mode: "raw",
              raw: JSON.stringify({
                  consumer: pm.environment.get("v_risk_management_consumer"),
                  consumerPassword: pm.environment.get("v_consumer_password")
              })
          }
      }, function (err, response) {
          if (err) {
              console.log("jwt-auth error:", err);
          } else {
              const jsonData = response.json();
              pm.collectionVariables.set("v_access_token", jsonData.accessToken);
          }
      });

