pm.test("HTTP status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("GenericResponse envelope", function () {
    pm.expect(jsonData).to.have.all.keys("responseCode", "responseMessage", "errorCode", "errorMsg", "correlationId", "response");
    pm.expect(jsonData.responseCode).to.eql("200");
    pm.expect(jsonData.responseMessage).to.eql("OK");
    pm.expect(jsonData.errorCode).to.eql(null);
    pm.expect(jsonData.errorMsg).to.eql(null);
    pm.expect(jsonData.correlationId).to.match(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
});

pm.test("response.countryList is an array of rows", function () {
    pm.expect(jsonData.response.countryList).to.be.an("array");
    jsonData.response.countryList.forEach(function (row) {
        pm.expect(row).to.have.property("name");
        pm.expect(row.iso2).to.match(/^[A-Z]{2}$/);
        pm.expect(row.iso3).to.match(/^[A-Z]{3}$/);
    });
});

